-- ============================================
-- LUMA — 4 nouveaux thèmes de vocabulaire : Musique, Animaux, Fruits &
-- Légumes, Vie sociale. 5 niveaux x 20 mots chacun, exercices inclus.
-- ============================================

insert into vocab_themes (language_id, slug, title, icon, position, words)
select id, v.slug, v.title, v.icon, v.position, '[]'::jsonb
from languages, (values
('musique', 'Musique', '🎵', 11),('animaux', 'Animaux', '🐾', 12),('fruits_legumes', 'Fruits & Légumes', '🍎', 13),('sociale', 'Vie sociale', '🤝', 14)
) as v(slug, title, icon, position)
where languages.code = 'en';

with t as (select id from vocab_themes where slug = 'musique')
insert into vocab_theme_levels (theme_id, position, title, words)
select t.id, 1, 'Niveau 1', '[{"en": "song", "fr": "chanson", "level": "A1"}, {"en": "singer", "fr": "chanteur", "level": "A1"}, {"en": "guitar", "fr": "guitare", "level": "A1"}, {"en": "piano", "fr": "piano", "level": "A1"}, {"en": "drum", "fr": "tambour/batterie", "level": "A1"}, {"en": "concert", "fr": "concert", "level": "A1"}, {"en": "band", "fr": "groupe (musique)", "level": "A1"}, {"en": "melody", "fr": "mélodie", "level": "A2"}, {"en": "rhythm", "fr": "rythme", "level": "A2"}, {"en": "lyrics", "fr": "paroles (chanson)", "level": "A2"}, {"en": "album", "fr": "album", "level": "A1"}, {"en": "radio", "fr": "radio", "level": "A1"}, {"en": "headphones", "fr": "écouteurs", "level": "A1"}, {"en": "microphone", "fr": "microphone", "level": "A1"}, {"en": "chorus", "fr": "refrain", "level": "A2"}, {"en": "tune", "fr": "air (mélodie)", "level": "A2"}, {"en": "instrument", "fr": "instrument", "level": "A1"}, {"en": "orchestra", "fr": "orchestre", "level": "A2"}, {"en": "dance (music)", "fr": "danse", "level": "A1"}, {"en": "sound", "fr": "son", "level": "A1"}]'::jsonb from t;

with l as (select id from vocab_theme_levels where theme_id = (select id from vocab_themes where slug = 'musique') and position = 1)
insert into vocab_theme_exercises (level_id, theme_id, position, type, content)
select l.id, (select id from vocab_themes where slug = 'musique'), v.position, v.type, v.content::jsonb from l, (values
(1, 'qcm', '{"question": "\"chanson\" = ?", "options": ["instrument", "song", "lyrics", "tune"], "correct_index": 1, "feedback_correct": "Correct !", "feedback_incorrect": "La bonne réponse est \"song\"."}'),(2, 'qcm', '{"question": "\"piano\" = ?", "options": ["tune", "microphone", "piano", "rhythm"], "correct_index": 2, "feedback_correct": "Correct !", "feedback_incorrect": "La bonne réponse est \"piano\"."}'),(3, 'matching', '{"instruction": "Relie le mot anglais à sa traduction.", "pairs": [{"left": "band", "right": "groupe (musique)"}, {"left": "melody", "right": "mélodie"}, {"left": "rhythm", "right": "rythme"}, {"left": "lyrics", "right": "paroles (chanson)"}], "feedback_correct": "Bravo !", "feedback_incorrect": "Regarde bien les mots."}'),(4, 'matching', '{"instruction": "Relie le mot anglais à sa traduction.", "pairs": [{"left": "headphones", "right": "écouteurs"}, {"left": "microphone", "right": "microphone"}, {"left": "chorus", "right": "refrain"}, {"left": "tune", "right": "air (mélodie)"}], "feedback_correct": "Bravo !", "feedback_incorrect": "Regarde bien les mots."}'),(5, 'fill_blank', '{"sentence_before": "\"orchestre\" = ", "sentence_after": "", "correct_answers": ["orchestra"], "feedback_correct": "Correct !", "feedback_incorrect": "\"orchestre\" se dit \"orchestra\" en anglais."}'),(6, 'true_false', '{"statement": "\"sound\" veut dire \"son\".", "correct_answer": true, "feedback_correct": "Correct !", "feedback_incorrect": "Regarde bien la traduction."}')
) as v(position, type, content);

