(1, 'qcm', '{"question": "\"socialité\" = ?", "options": ["cultural assimilation", "grassroots movement", "sociality", "in-group bias"], "correct_index": 2, "feedback_correct": "Correct !", "feedback_incorrect": "La bonne réponse est \"sociality\"."}'),(2, 'qcm', '{"question": "\"homophilie (affinité sociale)\" = ?", "options": ["social capital erosion", "code-switching", "homophily", "tribalism"], "correct_index": 2, "feedback_correct": "Correct !", "feedback_incorrect": "La bonne réponse est \"homophily\"."}'),(3, 'matching', '{"instruction": "Relie le mot anglais à sa traduction.", "pairs": [{"left": "confirmation bias (social)", "right": "biais de confirmation"}, {"left": "echo chamber", "right": "chambre d''écho (médias)"}, {"left": "tribalism", "right": "tribalisme"}, {"left": "polarization (social)", "right": "polarisation (sociale)"}], "feedback_correct": "Bravo !", "feedback_incorrect": "Regarde bien les mots."}'),(4, 'matching', '{"instruction": "Relie le mot anglais à sa traduction.", "pairs": [{"left": "grassroots movement", "right": "mouvement populaire/citoyen"}, {"left": "social fabric", "right": "tissu social"}, {"left": "communal identity", "right": "identité communautaire"}, {"left": "cultural assimilation", "right": "assimilation culturelle"}], "feedback_correct": "Bravo !", "feedback_incorrect": "Regarde bien les mots."}'),(5, 'fill_blank', '{"sentence_before": "\"microagression\" = ", "sentence_after": "", "correct_answers": ["microaggression"], "feedback_correct": "Correct !", "feedback_incorrect": "\"microagression\" se dit \"microaggression\" en anglais."}'),(6, 'true_false', '{"statement": "\"intersectionality\" veut dire \"intersectionnalité\".", "correct_answer": true, "feedback_correct": "Correct !", "feedback_incorrect": "Regarde bien la traduction."}')
) as v(position, type, content);
